head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vMktactCd = '320';
scwin.vBndListProcsTpCd = 1; // 채권처리구분(1:신청,2:접수)
scwin.vDtlInfoRowCount = 0;
scwin.vViewYN = 'N';
scwin.vRowPos = 0;
scwin.vSaleRow = 0;
scwin.vIsuCd = '', scwin.vCheck_DuplCnt = '', scwin.hasAttachDoc = '';
scwin.gBndApplId = '', scwin.gProcsStat = '';
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.processGp; // 접수 1, 반송 2, 처리완료 3, 수정 4, 팀장확인 6, 표준코드요청 9
scwin.btnStat = new Object();
scwin.vRetRow = 0, scwin.vRetRowApplCnt = 0;
scwin.objRowPos = new Object();

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        $c.bns.BnsPanelToGroupBox(pnl_Req); // 패널라운드처리(신청)
        $c.bns.BnsPanelToGroupBox(pnl_DtlInfo1); // 패널라운드처리(신청상세)
        $c.bns.BnsPanelToGroupBox(pnl_Acpt); // 패널라운드처리(접수)

        tab_List.setSelectedTabIndex(1);
        scwin.listSync(); // 목록 조회

        // 팀장확인데이터셋설정

        // dts_Temp.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
        dts_Temp.insertRow();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05500.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name tab_List_OnSelChanged
 * @description tab List On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {void}
 * @hidden N
 */
scwin.tab_List_OnSelChanged = function(nIndex) {
    try {
        scwin.vBndListProcsTpCd = nIndex;
        if (scwin.vBndListProcsTpCd === 2) {
            $c.bns.BnsPanelToGroupBox(pnl_DtlInfo2); // 패널라운드처리(접수상세)
            $c.bns.BnsPanelToGroupBox(pnl_IsuSales); // 패널라운드처리(종목일별 매출내역)

        }
        scwin.listSync(); // 목록 조회
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05500.tab_List_OnSelChanged" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS05500.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        if (scwin.vBndListProcsTpCd === 2) {

            // 접수,수정,팀장확인,처리완료 시 해당 ROW로 이동
            if (scwin.objRowPos.ISU_CD !== undefined) {
                scwin.rowPosPack(dts_List);
            }
            // 반송 시, 신청건수가 1건 이상은 해당 ROW로 이동
            if (scwin.vRetRowApplCnt > 1) {
                dts_List.setRowPosition(scwin.vRetRow, 0);
            }

            // 중복조치건은 그리드 색깔 변경. 2024.08.23
            // 일별금액조정-기타변경, 일별금액조정-월별금액조정  중복조치가 가능
            scwin.changeGridBgColor();
        } else {
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05500.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_List2_onheadcheckclick
 * @description grd_List2 onheadcheckclick 이벤트
 * @param {*} col col
 * @param {*} colid colid
 * @param {*} bCheck bCheck
 * @returns {void}
 * @hidden N
 */
scwin.grd_List2_onheadcheckclick = function(col, colid, bCheck) {
    try {
        scwin.setCheckBoxALL(grd_List2, dts_List, bCheck);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05500.grd_List2_onheadcheckclick" });
    }
};

/**
 * @method
 * @name dts_List_OnRowPosChanged
 * @description List On Row Pos Changed 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnRowPosChanged = function(row) {
    try {
        if (row > 0) {
            scwin.gBndApplId = dts_List.getCellData(row, "BND_APPL_ID");
            scwin.vIsuCd = dts_List.getCellData(row, "ISU_CD");
            scwin.dtlSync();
            if (scwin.vBndListProcsTpCd === 2) {
                scwin.salesSync();
            }
            scwin.gProcsStat = dts_List.getCellData(row, "PROCS_STAT");
            scwin.procBtnStat();
        } else {
            dts_DtlInfo.removeAll();
            scwin.vDtlInfoRowCount = 0;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05500.dts_List_OnRowPosChanged" });
    }
};

/**
 * @method
 * @name dts_DtlInfo_OnLoadError
 * @description dts_DtlInfo 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DtlInfo_OnLoadError = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS05500.dts_DtlInfo_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_DtlInfo_OnLoadCompleted
 * @description dts_DtlInfo 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_DtlInfo_OnLoadCompleted = function(rowcount) {
    try {
        scwin.vDtlInfoRowCount = rowcount;

        // 매출초일여부 체크 설정
        if (dts_DtlInfo.getCellData(1, "FST_SALE_DD_YN") === 'Y') {
            chk_FstSaleDdYn.setValue(1);
        } else {
            chk_FstSaleDdYn.setValue(0);
        }
        edt_BfchgListAmt.RightMargin = 5;
        edt_BndSaleTotamt.RightMargin = 5;
        edt_RedmptAmt.RightMargin = 5;
        edt_NetSaleAmt.RightMargin = 5;
        edt_IsuAmt.RightMargin = 5;
        edt_CoupnRt.RightMargin = 5;
        edt_BfchgListAmt2.RightMargin = 5;
        edt_NetSaleAmt2.RightMargin = 5;
        edt_AfchgListAmt.RightMargin = 5;

        // 중복조치가된 건의 변경후 상장금액 항목을 빨간색을 변경
        if (scwin.vBndListProcsTpCd === 2) {
            scwin.changeAfchgListAmtBgColor();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05500.dts_DtlInfo_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_SalesList_OnLoadCompleted
 * @description dts_SalesList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_SalesList_OnLoadCompleted = function(rowcount) {
    try {
        // 접수, 수정이 되었을 경우 해당 위치로
        if (scwin.vRowPos > 0) {
            if (scwin.objRowPos.ISU_CD !== undefined) {
                scwin.vSaleRow = $c.cp.getNameValueRow(dts_SalesList, "BND_APPL_ID", scwin.vRowPos);
            }
            dts_SalesList.setRowPosition(scwin.vSaleRow, 0);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05500.dts_SalesList_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_SalesList_OnRowPosChanged
 * @description Sales List On Row Pos Changed 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_SalesList_OnRowPosChanged = function(row) {
    try {
        if (row > 0) {
            scwin.gBndApplId = dts_SalesList.getCellData(row, "BND_APPL_ID");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05500.dts_SalesList_OnRowPosChanged" });
    }
};

/**
 * @method
 * @name img_StrtDd_onclick
 * @description img_StrtDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_StrtDd_onclick = function() {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        popUpCalendar2(edt_StrtDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05500.img_StrtDd_onclick" });
    }
};

/**
 * @method
 * @name img_StrtDd2_onclick
 * @description img_StrtDd2 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_StrtDd2_onclick = function() {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        popUpCalendar2(edt_StrtDd2);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05500.img_StrtDd2_onclick" });
    }
};

/**
 * @method
 * @name img_Saledd_onclick
 * @description img_Saledd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_Saledd_onclick = function() {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        popUpCalendar2(edt_SaleDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05500.img_Saledd_onclick" });
    }
};

/**
 * @method
 * @name btn_Acpt_onclick
 * @description 「접수」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Acpt_onclick = async function() {
    try {
        scwin.processGp = '1';
        await scwin.acpt();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS05500.btn_Acpt_onclick" });
    }
};

/**
 * @method
 * @name btn_Ret_onclick
 * @description 「반송」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Ret_onclick = function() {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        scwin.processGp = '2';
        scwin.fn_GetPar = scwin.getReturn;
        scwin.fn_SetPar = scwin.setReturn;
        $c.bns.fn_PopReturn(grd_List1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05500.btn_Ret_onclick" });
    }
};

/**
 * @method
 * @name btn_Ret2_onclick
 * @description 「반송」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Ret2_onclick = function() {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        // 접수 후 수정 및 반송시 체크한다.
        if ($c.bns.fn_CheckModAndRet('ULDBNS05500.xml', dts_CheckCmData, scwin.gBndApplId) > 0) return;
        scwin.processGp = '2';
        scwin.fn_GetPar = scwin.getReturnAppl;
        scwin.fn_SetPar = scwin.setReturn;
        $c.bns.fn_PopReturn(grd_List1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05500.btn_Ret2_onclick" });
    }
};

/**
 * @method
 * @name btn_Attach_onclick
 * @description 「첨부파일확인」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Attach_onclick = async function() {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        if ("N" === dts_DtlInfo.getCellData(1, "HAS_ATTACH_DOC")) {
            await $c.win.alert("연결된 팩스/첨부문서가 없습니다.");
            return;
        }
        scwin.fn_GetPar = scwin.getCommonKey;
        $c.bns.fn_PopAttachDocSearch(grd_List1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS05500.btn_Attach_onclick" });
    }
};

/**
 * @method
 * @name btn_Attach2_onclick
 * @description 「첨부파일확인」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Attach2_onclick = async function() {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        if ("N" === dts_SalesList.getCellData(dts_SalesList.getRowPosition(), "HAS_ATTACH_DOC")) {
            await $c.win.alert("연결된 팩스/첨부문서가 없습니다.");
            return;
        }
        scwin.fn_GetPar = scwin.getCommonKey;
        $c.bns.fn_PopAttachDocSearch(grd_List1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS05500.btn_Attach2_onclick" });
    }
};

/**
 * @method
 * @name btn_Dtl_onclick
 * @description 「종목상세내역」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Dtl_onclick = function() {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        scwin.fn_GetPar = scwin.getParIsuDelInfo;
        $c.bns.fn_PopIsuDetail(grd_List1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05500.btn_Dtl_onclick" });
    }
};

/**
 * @method
 * @name btn_Dtl2_onclick
 * @description 「종목상세내역」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Dtl2_onclick = function() {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        scwin.fn_GetPar = scwin.getParIsuDelInfo;
        $c.bns.fn_PopIsuDetail(grd_List1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05500.btn_Dtl2_onclick" });
    }
};

/**
 * @method
 * @name btn_Noti_onclick
 * @description 「매출통보내역」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Noti_onclick = function() {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        scwin.fn_GetPar = scwin.getParIsuDelInfo;
