    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05500.btn_Noti_onclick" });
    }
};

/**
 * @method
 * @name btn_Noti2_onclick
 * @description 「매출통보내역」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Noti2_onclick = function() {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        scwin.fn_GetPar = scwin.getParIsuDelInfo;
        $c.bns.fn_PopSalesNotiList(grd_List1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05500.btn_Noti2_onclick" });
    }
};

/**
 * @method
 * @name btn_ApprovFileCreat_onclick
 * @description 「결재파일생성」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_ApprovFileCreat_onclick = function() {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        scwin.fn_GetPar = scwin.getParApprovFileWrt;
        $c.bns.fn_PopApprovFileWrt(grd_List1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05500.btn_ApprovFileCreat_onclick" });
    }
};

/**
 * @method
 * @name btn_Proc_onclick
 * @description 「처리완료」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Proc_onclick = async function() {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        if (scwin.btnStat.Proc === "dis") return;
        scwin.objRowPos.STRT_DD = edt_StrtDd2.getValue();
        scwin.objRowPos.ISU_CD = txb_IsuCd2.getValue();
        scwin.processGp = '3';
        await scwin.procsComplt();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS05500.btn_Proc_onclick" });
    }
};

/**
 * @method
 * @name btn_Mod_onclick
 * @description 「수정」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Mod_onclick = async function() {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        // 필수입력값 체크
        if (await scwin.inputCheck() === false) return;
        scwin.fn_GetPar = scwin.getCommonKey;
        scwin.fn_SetPar = scwin.setReturnMod;
        await scwin.popUpdate(grd_List1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS05500.btn_Mod_onclick" });
    }
};

/**
 * @method
 * @name btn_TeamleadrConfrm_onclick
 * @description 「팀장확인」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_TeamleadrConfrm_onclick = async function() {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        // objRowPos.STRT_DD = dts_List.NameValue(dts_List.RowPosition, "STRT_DD");
        // objRowPos.ISU_CD = getObjectValue(txb_IsuCd2);
        scwin.processGp = "6";

        // 체크된 것 카운팅
        let nTrueCnt = 0;
        for (let nRow = 1; nRow <= dts_List.getRowCount(); nRow++) {
            if (dts_List.getCellData(nRow, "CHK") === "T") {
                nTrueCnt++;
            }
        }
        if (nTrueCnt === 0) {
            await $c.win.alert("선택된 정보가 없습니다.");
            return false;
        }
        $c.bns.fn_TeamleadrConfrmAll320('ULDBNS05500.xml', trs_Save, dts_List, scwin.vBndListProcsTpCd, nTrueCnt);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS05500.btn_TeamleadrConfrm_onclick" });
    }
};

/**
 * @method
 * @name dts_CheckCnt_OnLoadCompleted
 * @description dts_CheckCnt 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_CheckCnt_OnLoadCompleted = function(rowcount) {
    try {
        scwin.vCheck_DuplCnt = dts_CheckCnt.getRowCount();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS05500.dts_CheckCnt_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        if (scwin.processGp === '1') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A002", "접수"));
        }
        if (scwin.processGp === '3') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A002", "처리완료"));
        }
        if (scwin.processGp === '6') {
            await $c.win.alert($c.stf.getMessageParam("MSG-A002", "팀장확인"));
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS05500.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
