/**
 * @method
 * @name inputCheck
 * @description 필수 입력 값을 체크한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.inputCheck = async function() {
    if (scwin.vBndListProcsTpCd === 1) {
        if (edt_StrtDd.getValue() === '') {
            await $c.win.alert("[적용일]을 입력하십시오.");
            edt_StrtDd.focus();
            return false;
        }
        if ($c.bns.fn_CheckDateObj(edt_StrtDd, "적용일")) {
            return false;
        }
        if (edt_SaleDd.getValue() === '') {
            await $c.win.alert("[매출일]을 입력하십시오.");
            edt_SaleDd.focus();
            return false;
        }
        if ($c.bns.fn_CheckDateObj(edt_SaleDd, "매출일")) {
            return false;
        }
        if (edt_BndSaleTotamt.getValue() === '') {
            await $c.win.alert("[일중 매출총액]을 입력하십시오.");
            edt_BndSaleTotamt.focus();
            return false;
        }
        if (edt_RedmptAmt.getValue() === '') {
            await $c.win.alert("[일중 중도상환액]을 입력하십시오.");
            edt_RedmptAmt.focus();
            return false;
        }
    } else {
        if (edt_StrtDd2.getValue() === '') {
            await $c.win.alert("[적용일]을 입력하십시오.");
            edt_StrtDd2.focus();
            return false;
        }
        if ($c.bns.fn_CheckDateObj(edt_StrtDd2, "적용일")) {
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name ddPackTeamleadrConfrm
 * @description (일별금액조정 전용) 팀장확인을 처리한다.
 * @param {*} 'ULDBNS05500.xml' 'ULDBNS05500.xml'
 * @param {*} trsObj trsObj
 * @param {String} confrmDd confrmDd
 * @param {String} vAllBndApplId vAllBndApplId
 * @param {String} vBndListProcsTpCd vBndListProcsTpCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ddPackTeamleadrConfrm = async function('ULDBNS05500.xml', trsObj, confrmDd, vAllBndApplId, vBndListProcsTpCd) {
    // 담당자는 팀장확인 안됨.
    if (js_jobtitl === '03') {
        await $c.win.alert('팀장권한만 가능합니다.');
        return;
    }
    if (confrmDd !== "undefined" && confrmDd !== '-' && confrmDd !== '') {
        if (!window.confirm("이미 팀장확인처리되었습니다. 재처리하실경우 다시 시장지파일이 전송됩니다. \n 팀장확인처리하시겠습니까?")) return;
    } else {
        if (!window.confirm("팀장확인처리일자가 시장지파일 전송일자입니다. \n 팀장확인처리하시겠습니까?")) return;
    }
    dts_Temp.UseChangeInfo = "False";
    let url = "/bns/IsuChgAmt.do?method=processTeamleadrConfrm";
    url += "&SCREN_ID=" + 'ULDBNS05500.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    url += "&ALL_BND_APPL_ID=" + vAllBndApplId;
    url += "&BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd;
    trsObj.Action = $c.lc.fn_encodeNSession(url);
    trsObj.KeyName = "toinb_dataid4";
    trsObj.KeyValue = "JSP(I:pInput=dts_Temp)";
    trsObj.Post();
};

/**
 * @method
 * @name acptProcsCheck
 * @description 접수, 처리완료시 공통 체크 구문
 * @param {*} gubun gubun
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.acptProcsCheck = async function(gubun) {
    // 필수입력값 체크
    if (await scwin.inputCheck() === false) return 1;
    if (gubun === 'Acpt') {
        // 적용일,매매일,마감일,채권마감 체크
        if ($c.bns.fn_CheckCmData('ULDBNS05500.xml', dts_CheckCmData, edt_StrtDd.getValue(), scwin.gBndApplId) > 0) return 1;
    } else if (gubun === 'Procs') {
        // 적용일,매매일,마감일,채권마감 체크
        if ($c.bns.fn_CheckCmData('ULDBNS05500.xml', dts_CheckCmData, edt_StrtDd2.getValue(), scwin.gBndApplId) > 0) return 1;
    }
    scwin.vIsuCd = dts_DtlInfo.getCellData(1, "ISU_CD");
    scwin.hasAttachDoc = dts_DtlInfo.getCellData(1, "HAS_ATTACH_DOC");

    // 변경된 데이터가 없더라도 데이터셋 전송
    dts_DtlInfo.UseChangeInfo = "False";
    return 0;
};

/**
 * @method
 * @name acpt
 * @description 신청데이터를 접수 처리한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.acpt = async function() {
    // 접수, 처리완료 공통 체크
    if (await scwin.acptProcsCheck('Acpt') > 0) return;

    // 복수조치 체크
    if ($c.bns.fn_CheckMultActImpsblRule('ULDBNS05500.xml', dts_Temp, scwin.vIsuCd, scwin.vMktactCd, edt_StrtDd.getValue()) > 0) return;

    // 접수내역의 신청건수 체크
    if (await scwin.applCntCheck() > 0) {
        // 동일종목,동일매출기관,동일매출일이 접수내역에 있는제 체크 jackal_200320
        if (await scwin.applCntCheckInstDupl() > 0) {
            await $c.win.alert("동일종목에 대하여 동일매출기관의 동일매출일이 접수내역이 있습니다." + "\n해당종목의 접수내역을 확인하여 주시기 바랍니다.");
            return;
        }

        // 동일종목에 대한 적용일이 다른 접수내역에 있는지 체크
        if (await scwin.sameIsuOtherAcptYN() > 1) {
            await $c.win.alert("동일종목에 대하여 조치일이 다른 접수내역이 있습니다." + "\n각 접수내역의 조치일을 일치시켜 주시기 바랍니다.");
        } else {
            let vTeamleadOrProcs;
            vTeamleadOrProcs = "TEAMLEARD"; // 팀장확인된 종목이 있는가 체크
            if (await scwin.teamLeaderOrProcsCnt(vTeamleadOrProcs) > 0) {
                await $c.win.alert("동일종목에 대하여 이미 팀장확인된 신청내역이 있습니다." + "\n이 경우 현재 신청내역의 접수처리시 자동으로 처리완료가 됩니다.");
                // 팀장확인 처리
                scwin.processGp = "6";
                const confrmDd = dts_List.getCellData(dts_List.getRowPosition(), "TEAMLEADER_CONFRM_DD");
                $c.bns.fn_TeamleadrConfrm1('ULDBNS05500.xml', trs_Save, confrmDd, scwin.gBndApplId, scwin.vBndListProcsTpCd);
            }
            vTeamleadOrProcs = "PROCS_COMPLT"; // 처리완료된 종목이 있는가 체크
            if (await scwin.teamLeaderOrProcsCnt(vTeamleadOrProcs) > 0) {
                await $c.win.alert("동일종목에 대하여 이미 처리완료된 신청내역이 있습니다." + "\n이 경우 현재 신청내역의 접수처리시 자동으로 처리완료가 됩니다.");
                // 처리완료 처리
                scwin.processGp = '3';
                await scwin.procsComplt();
            }
        }
    }

    // 첨부문서 체크
    if (!$c.bns.fn_EndConfirm(scwin.hasAttachDoc, '접수')) return;
    let url = "/bns/IsuChgAmt.do?method=processApplAcpt";
    url += "&SCREN_ID=" + 'ULDBNS05500.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    url += "&MKTACT_TP_CD=" + scwin.vMktactCd;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_DtlInfo)";
    trs_Save.Post();
};

/**
 * @method
 * @name getApplId
 * @description 종목코드별 신청ID를 리턴한다.
 * @returns {void}
 * @hidden N
 */
scwin.getApplId = function() {
    let applId = '';
    let returnVal = '';
    for (let i = 0; dts_SalesList.getRowCount() > i; i++) {
        applId = dts_SalesList.getCellData(i + 1, "BND_APPL_ID");
        returnVal += "'" + applId + "',";
    }
    return returnVal.substring(0, returnVal.length - 1);
};

/**
 * @method
 * @name procsComplt
 * @description 처리완료 를 처리한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.procsComplt = async function() {
    // 접수, 처리완료 공통 체크
    if (await scwin.acptProcsCheck('Procs') > 0) return;

    // 복수조치 체크
    // 일별금액조정-기타변경, 일별금액조정-월별금액조정은 복수시장조치가 가능하다. 2024.08.23 by no3
    // 아래 함수는 고칠것 없음. TBLD_B_MULTACT_IMPSBL_RULE의 데이터 변경으로 복수시장조치 가능하도록 수정함.
    if ($c.bns.fn_CheckMultActImpsblRuleProcEnd('ULDBNS05500.xml', dts_Temp, scwin.vIsuCd, scwin.vMktactCd, edt_StrtDd2.getValue()) > 0) return;

    // 중복시장조치코드에따른 alert
    if (dts_List.getCellData(dts_List.getRowPosition(), "DUP_MKTACT_CD") === "316") {
        await $c.win.alert("기타변경 화면과 중복조치가 발생했습니다.\n\"변경 후 상장금액\"을 확인하시기 바랍니다.");
    } else if (dts_List.getCellData(dts_List.getRowPosition(), "DUP_MKTACT_CD") === "301") {
        await $c.win.alert("일괄상장 월별금액조정 화면과 중복조치가 발생했습니다.\n\"변경 후 상장금액\"을 확인하시기 바랍니다.");
    }

    // 동일종목에 대한 적용일이 다른 접수내역에 있는지 체크
    if (await scwin.sameIsuOtherAcptYN() > 1) {
        await $c.win.alert("동일종목에 대하여 조치일이 다른 접수내역이 있습니다." + "\n각 접수내역의 조치일을 일치시켜 주시기 바랍니다.");
    }
    let url;
    if (scwin.processGp === '3') {
        if (!confirm("처리완료 하시겠습니까?")) return;
        url = "/bns/IsuChgAmt.do?method=processAcptProcessComplt";
    }
    url += "&SCREN_ID=" + 'ULDBNS05500.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    url += "&MKTACT_TP_CD=" + scwin.vMktactCd;
    url += "&ALL_BND_APPL_ID=" + scwin.getApplId();
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_DtlInfo)";
    trs_Save.Post();
};

