        scwin.vRowPos = dts_SalesList.getCellData(dts_SalesList.getRowPosition(), "BND_APPL_ID");
        scwin.objRowPos.STRT_DD = arrPar[0].STRT_DD;
        scwin.objRowPos.ISU_CD = txb_IsuCd2.getValue();
