        dts_SalesList.Reset();
    }
};

/**
 * @method
 * @name teamleadrConfrm
 * @description 일별금액조정 팀장확인을 처리한다.
 * @param {*} 'ULDBNS05500.xml' 'ULDBNS05500.xml'
 * @param {*} trsObj trsObj
 * @param {String} confrmDd confrmDd
 * @param {*} gBndApplIds gBndApplIds
 * @param {String} vBndListProcsTpCd vBndListProcsTpCd
 * @returns {void}
 * @hidden N
 */
scwin.teamleadrConfrm = function('ULDBNS05500.xml', trsObj, confrmDd, gBndApplIds, vBndListProcsTpCd) {
    if (confrmDd !== "undefined" && confrmDd !== '-' && confrmDd !== '') {
        if (!window.confirm("이미 팀장확인처리되었습니다. 재처리하실경우 다시 시장지파일이 전송됩니다. \n 팀장확인처리하시겠읍니까?")) return;
    } else {
        if (!window.confirm("팀장확인처리일자가 시장지파일 전송일자입니다. \n 팀장확인처리하시겠읍니까?")) return;
    }
    let url = "/bns/IsuChgAmt.do?method=processTeamleadrConfrm";
    url += "&SCREN_ID=" + 'ULDBNS05500.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    url += "&ALL_BND_APPL_ID=" + gBndApplIds;
    url += "&BND_LIST_PROCS_TP_CD=" + scwin.vBndListProcsTpCd;
    trsObj.Action = $c.lc.fn_encodeNSession(url);
    trsObj.KeyName = "toinb_dataid4";
    trsObj.KeyValue = "JSP(I:pInput=dts_Temp)";
    trsObj.Post();
};

/**
 * @method
 * @name getCommonKey
 * @description 팝업에 넘길 키데이터를 정의한다.
