/**
 * @method
 * @name rowPosPack
 * @description DataSet Reset시 해당 ROW로 이동
 * @param {*} dts_List dts_List
 * @returns {void}
 * @hidden N
 */
scwin.rowPosPack = function(dts_List) {
    let vRow = 0;
    for (let i = 1; i <= dts_List.getRowCount(); i++) {
        if (scwin.objRowPos.ISU_CD === dts_List.getCellData(i, 'ISU_CD') && scwin.objRowPos.STRT_DD === dts_List.getCellData(i, 'STRT_DD')) {
            vRow = i;
            break;
        }
    }
    dts_List.setRowPosition(dts_List.getRowCount(), 0);
    dts_List.setRowPosition(vRow, 0);
};

/**
 * @method
 * @name setCheckBoxALL
 * @description 그리드 체크박스 전체선택 또는 전체선택 해제
 * @param {*} grdObj grdObj
 * @param {*} dtsObj dtsObj
 * @param {*} bCheck bCheck
 * @returns {void}
 * @hidden N
 */
scwin.setCheckBoxALL = function(grdObj, dtsObj, bCheck) {
    let vcd = "";
    if (bCheck === '1') {
        vcd = "T";
    } else {
        vcd = "F";
    }
    grdObj.setBroadcast(false);
    for (let i = 1; i <= dtsObj.getRowCount(); i++) {
        if (dtsObj.getCellData(i, "PROCS_STAT") !== '처리완료' || (dtsObj.getCellData(i, "TEAMLEADER_CONFRM_DD") !== "undefined" && dtsObj.getCellData(i, "TEAMLEADER_CONFRM_DD") !== '-' && dtsObj.getCellData(i, "TEAMLEADER_CONFRM_DD") !== '')) {
            // 처리완료만 팀장확인 대상임
            dtsObj.setCellData(i, "CHK", "F");
        } else {
            dtsObj.setCellData(i, "CHK", vcd);
        }
    }
    grdObj.setBroadcast(true);
};

/**
 * @method
 * @name setTransData
 * @description 선택된 row의 값을 강제로 변경.. 이렇게 하면 변경된 row만 서버로 전송될것 같아서..
 * @returns {void}
 * @hidden N
 */
scwin.setTransData = function() {
    let nRow = dts_List.getRowPosition();
    dts_List.setCellData(nRow, "CHK", "T");
};

/**
 * @method
 * @name changeGridBgColor
 * @description 중복조치 발생한 row는 빨간색으로 변경
 * @returns {void}
 * @hidden N
 */
scwin.changeGridBgColor = function() {
    // 그리드 컬럼 ID 구하기
    const arrColID = [];
    for (let i = 0; i < grd_List2.getTotalCol(); i++) {
        arrColID.push(grd_List2.getColumnID(i));
    }

    // 평가등급 일치여부가 N인 로우의 배경색 Light Yellow로 설정
    for (let j = 0; j < arrColID.length; j++) {
        $c.cm.setColumnProp(grd_List2, arrColID[j], 'BgColor', "{decode(DUP_MKTACT_CD,'316','#FF9898','301','#FF9898',decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff'))}");
    }
};

/**
 * @method
 * @name changeAfchgListAmtBgColor
 * @description 중복조치 발생한건의 변경후상장금액 항목 빨간색으로 변경
 * @returns {void}
 * @hidden N
 */
scwin.changeAfchgListAmtBgColor = function() {
    const DUP_MKTACT_CD = dts_List.getCellData(dts_List.getRowPosition(), "DUP_MKTACT_CD");
    if (DUP_MKTACT_CD !== "") {
        edt_AfchgListAmt.ReadOnlyBackColor = "#FF9898";
    } else {
        edt_AfchgListAmt.ReadOnlyBackColor = "#b9d4f7";
    }
    edt_AfchgListAmt.RightMargin = 5;
};
